package com.cryptostrategy.platform.leaderboard.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.experiment.api.ExperimentId;import com.cryptostrategy.platform.leaderboard.api.model.LeaderboardRevision;import com.cryptostrategy.platform.leaderboard.api.port.out.LeaderboardStore;import java.util.*;import org.junit.jupiter.api.Test;
class LeaderboardServiceTest{@Test void filtersIneligibleAndReusesUnchangedRevision(){ExperimentId experiment=new ExperimentId("00000000000000000000000030");class MemoryStore implements LeaderboardStore{LeaderboardRevision value;int saves;public Optional<LeaderboardRevision> latest(ExperimentId id){return Optional.ofNullable(value);}public LeaderboardRevision save(LeaderboardRevision r){saves++;return value=r;}public List<EvaluationResult> listEvaluationsForExperiment(ExperimentId experimentId, int limit){return List.of();}}MemoryStore store=new MemoryStore();LeaderboardService service=new LeaderboardService(store);var eligible=LeaderboardTestFixtures.evaluation("00000000000000000000000031",experiment,"0.8","a",true);var ineligible=LeaderboardTestFixtures.evaluation("00000000000000000000000032",experiment,"0.9","b",false);var first=service.project(experiment,new RankingVersion("ranking-v1"),10,List.of(ineligible,eligible));var second=service.project(experiment,new RankingVersion("ranking-v1"),10,List.of(eligible,ineligible));assertSame(first,second);assertEquals(1,store.saves);assertEquals(1,first.entries().size());}}
